class Solution {
public:
    bool canConstruct(string ransomNote, string magazine) {
        vector<int> counts(26, 0);
        for (char c : magazine) counts[c - 'a']++;
        for (char c : ransomNote) {
            if (--counts[c - 'a'] < 0) return false;
        }
        return true;
    }
};

class Solution {
    public boolean canConstruct(String ransomNote, String magazine) {
        int[] counts = new int[26];
        for (int i = 0; i < magazine.length(); i++) counts[magazine.charAt(i) - 'a']++;
        for (int i = 0; i < ransomNote.length(); i++) {
            if (--counts[ransomNote.charAt(i) - 'a'] < 0) return false;
        }
        return true;
    }
}

var canConstruct = function(ransomNote, magazine) {
    const counts = new Map();
    for (const c of magazine) counts.set(c, (counts.get(c) || 0) + 1);
    for (const c of ransomNote) {
        const cnt = counts.get(c) || 0;
        if (cnt <= 0) return false;
        counts.set(c, cnt - 1);
    }
    return true;
};
